const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
if (data.length === 0) process.exit(0);

const n = data[0];
const adj = Array.from({ length: n + 1 }, () => []);

for (let i = 1; i < data.length; i += 2) {
  const a = data[i];
  const b = data[i + 1];
  adj[a].push(b);
  adj[b].push(a);
}

const parent = new Int32Array(n + 1);
parent[1] = -1;

const order = new Int32Array(n);
let idx = 0;

const stack = [1];
while (stack.length > 0) {
  const v = stack.pop();
  order[idx++] = v;

  const p = parent[v];
  for (let j = 0; j < adj[v].length; j++) {
    const u = adj[v][j];
    if (u !== p) {
      parent[u] = v;
      stack.push(u);
    }
  }
}

const size = new Int32Array(n + 1);
let ans = n;

for (let i = n - 1; i >= 0; i--) {
  const v = order[i];
  size[v]++;

  if (parent[v] > 0) {
    const s = size[v];
    const diff = Math.abs(n - 2 * s);
    if (diff < ans) ans = diff;
    size[parent[v]] += s;
  }
}

console.log(ans);
